<?php

declare(strict_types=1);

namespace Waynestate\Advisor\Content;

use RuntimeException;

/**
 * The stack parts table, rendered from the project seed.
 *
 * The table lives between two markers in a README:
 *
 *     <!-- stack-parts:start -->
 *
 *     <!-- generated by advisor stack-parts; edit ADVISOR's projects.seed.json -->
 *
 *     | Part | What it is |
 *     |---|---|
 *     | **WayneUI** | interface (project 0) |
 *
 *     <!-- stack-parts:end -->
 *
 * write() replaces everything between the markers and keeps the markers;
 * check() reports the files whose block is stale. A file without both
 * markers, in order, is an error and is never edited.
 */
final class PartsTable
{
    public const START_MARKER = '<!-- stack-parts:start -->';

    public const END_MARKER = '<!-- stack-parts:end -->';

    public const GENERATED_NOTE = "<!-- generated by advisor stack-parts; edit ADVISOR's projects.seed.json -->";

    private function __construct() {}

    /**
     * The table, one row per project, in seed order.
     *
     * @param list<array{name: string, tagline: string}> $projects
     */
    public static function render(array $projects): string
    {
        $lines = ['| Part | What it is |', '|---|---|'];
        foreach ($projects as $project) {
            $lines[] = '| **' . $project['name'] . '** | ' . $project['tagline'] . ' |';
        }

        return implode("\n", $lines) . "\n";
    }

    /**
     * The block that belongs between the markers: a blank line, the generated
     * note, a blank line, the table, a blank line.
     *
     * @param list<array{name: string, tagline: string}> $projects
     */
    public static function block(array $projects): string
    {
        return "\n" . self::GENERATED_NOTE . "\n\n" . self::render($projects);
    }

    /**
     * Replace the block between the markers in the file. The markers
     * themselves are kept. A file without both markers, in order, is an error
     * and is left untouched.
     *
     * @param list<array{name: string, tagline: string}> $projects
     */
    public static function write(string $path, array $projects): void
    {
        [$lines, $start, $end] = self::markers($path);

        $lines = array_merge(
            array_slice($lines, 0, $start + 1),
            explode("\n", self::block($projects)),
            array_slice($lines, $end),
        );

        if (file_put_contents($path, implode("\n", $lines)) === false) {
            throw new RuntimeException("stack-parts: cannot write {$path}.");
        }
    }

    /**
     * Check each file's block against the table. Returns one line per file
     * that is stale or unmarked; an empty list means every file matches.
     *
     * @param list<string> $paths
     * @param list<array{name: string, tagline: string}> $projects
     *
     * @return list<string>
     */
    public static function check(array $paths, array $projects): array
    {
        $stale = [];
        foreach ($paths as $path) {
            try {
                [$lines, $start, $end] = self::markers($path);
            } catch (RuntimeException $e) {
                $stale[] = $e->getMessage();
                continue;
            }

            $current = implode("\n", array_slice($lines, $start + 1, $end - $start - 1));
            if ($current !== self::block($projects)) {
                $stale[] = $path;
            }
        }

        return $stale;
    }

    /**
     * @return array{0: list<string>, 1: int, 2: int} the lines and the start and end marker line numbers
     */
    private static function markers(string $path): array
    {
        $raw = @file_get_contents($path);
        if ($raw === false) {
            throw new RuntimeException("stack-parts: cannot read {$path}.");
        }

        $lines = explode("\n", str_replace(["\r\n", "\r"], "\n", $raw));
        $start = self::markerLine($lines, self::START_MARKER, 'start', $path);
        $end = self::markerLine($lines, self::END_MARKER, 'end', $path);
        if ($end <= $start) {
            throw new RuntimeException("stack-parts: {$path} has its end marker before its start marker.");
        }

        return [$lines, $start, $end];
    }

    /**
     * @param list<string> $lines
     */
    private static function markerLine(array $lines, string $marker, string $which, string $path): int
    {
        foreach ($lines as $i => $line) {
            if (trim($line) === $marker) {
                return $i;
            }
        }

        throw new RuntimeException("stack-parts: {$path} is missing its {$which} marker ({$marker}).");
    }
}
